from pathlib import Path

ROOT = Path('/app') if Path('/app/scenario.json').exists() else Path(__file__).resolve().parents[1]
CONFIG_PATH = Path('/app/scenario.json') if Path('/app/scenario.json').exists() else ROOT / 'data/input.json'
CONFIG = json.loads(CONFIG_PATH.read_text())
INPUT = json.loads((ROOT / 'data/workload.json').read_text())
PARSER = argparse.ArgumentParser()
PARSER.add_argument('--stage', required=True, choices=CONFIG['stages'])
PARSER.add_argument('--output', default=str(ROOT / 'outputs'))
ARGS = PARSER.parse_args()
OUT = Path(ARGS.output)
OUT.mkdir(parents=True, exist_ok=True)
STAGE = ARGS.stage


def read_stage(name):
    record = json.loads((OUT / f'stage-{name}.json').read_text())
    if record['status'] != 'success' or record['stage'] != name:
        raise ValueError(f'invalid upstream stage: {name}')
    return record['result']


def previous():
    parents = CONFIG['dependencies'][STAGE]
    if len(parents) != 1:
        raise ValueError(f'{STAGE} requires an explicit parent selection')
    return read_stage(parents[0])


def write_json(name, value):
    (OUT / name).write_text(json.dumps(value, indent=2, allow_nan=False) + '\n')
    return value


def write_pickle(name, value):
    (OUT / name).write_bytes(pickle.dumps(value, protocol=4))


def write_csv(name, rows):
    with (OUT / name).open('w', newline='') as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows(rows)


def report(name, title, value):
    (OUT / name).write_text('<!doctype html><meta charset="utf-8"><title>' + html.escape(title) + '</title><h1>' + html.escape(title) + '</h1><pre>' + html.escape(json.dumps(value, indent=2)) + '</pre>\n')


def regression(rows):
    xs = [row[0] for row in rows]
    ys = [row[1] for row in rows]
    mean_x, mean_y = statistics.mean(xs), statistics.mean(ys)
    denominator = sum((x - mean_x) ** 2 for x in xs)
    if denominator <= 0:
        raise ValueError('training inputs have zero variance')
    weight = sum((x - mean_x) * (y - mean_y) for x, y in rows) / denominator
    return {'weight': weight, 'bias': mean_y - weight * mean_x}


def predict(model, x):
    return model['weight'] * x + model['bias']


def rmse(model, rows):
    return math.sqrt(statistics.mean((predict(model, x) - y) ** 2 for x, y in rows))


def require(condition, message):
    if not condition:
        raise ValueError(message)


def run_stage():
    started = time.time_ns()
    parents = CONFIG['dependencies'][STAGE]
    for parent in parents:
        read_stage(parent)
    result = compute()
    require(isinstance(result, dict) and result, 'activity produced no domain result')
    record = {
        'showcase': CONFIG['slug'], 'stage': STAGE, 'status': 'success',
        'validationMode': 'local-workload', 'startedAtUnixNs': started,
        'finishedAtUnixNs': time.time_ns(),
        'inputDigest': hashlib.sha256(json.dumps(INPUT, sort_keys=True).encode()).hexdigest(),
        'dependencies': parents, 'result': result,
    }
    write_json(f'stage-{STAGE}.json', record)
    print(json.dumps({'activity': STAGE, 'status': 'success', 'resultKeys': list(result)}))

def experiment_response(x):
    return INPUT['offset'] - (x - INPUT['optimum']) ** 2


def feedback_loop():
    if STAGE == 'observations':
        xs = INPUT['observations']
        require(len(xs) >= 3, 'at least three observations are required')
        return {'observations': [[x, experiment_response(x)] for x in xs]}
    if STAGE == 'update-model':
        observations = previous()['observations']
        # Quadratic regression y = a*x^2 + b*x + c via Gaussian elimination.
        matrix = [[sum(x ** (i+j) for x, _ in observations) for j in range(3)] + [sum(y*x**i for x,y in observations)] for i in range(3)]
        for pivot in range(3):
            magnitude = matrix[pivot][pivot]
            require(abs(magnitude) > 1e-12, 'singular experiment design')
            matrix[pivot] = [v/magnitude for v in matrix[pivot]]
            for row in range(3):
                if row != pivot:
                    factor = matrix[row][pivot]
                    matrix[row] = [v-factor*p for v,p in zip(matrix[row],matrix[pivot])]
        coefficients = [matrix[i][-1] for i in range(3)]
        require(coefficients[2] < 0, 'feedback model is not concave')
        return {'coefficients': coefficients, 'observations': observations}
    if STAGE == 'propose-experiments':
        model = previous()
        c,b,a = model['coefficients']
        optimum = -b/(2*a)
        return {'proposals': [optimum-0.1, optimum, optimum+0.1], 'model': model}
    if STAGE == 'safety-check':
        batch = previous()
        require(all(INPUT['minimum'] <= x <= INPUT['maximum'] for x in batch['proposals']), 'proposal exceeds the experiment safety envelope')
        return batch
    if STAGE == 'run-experiments':
        batch = previous()
        return {'proposals': batch['proposals'], 'results': [[x,experiment_response(x)] for x in batch['proposals']], 'prior': batch['model']['observations']}
    if STAGE == 'record-observations':
        results = previous()
        best = max(results['results'],key=lambda row:row[1])
        require(abs(best[0]-INPUT['optimum']) < 1e-6, 'feedback failed to recover the optimum')
        write_json('next-batch.json', {'experiments': results['proposals']})
        report_data = {'before': results['prior'], 'after': results['results'], 'best': best, 'improvement': best[1]-max(y for _,y in results['prior'])}
        require(report_data['improvement'] > 0, 'feedback produced no improvement')
        write_json('feedback-report.json', report_data)
        return report_data
    raise ValueError(STAGE)


def compute():
    return feedback_loop()

if __name__ == '__main__':
    run_stage()
